function gitSpecToClone(spec) {
  const [head, ref] = spec.split("#");
  if (head.startsWith("github:")) return { url: `https://github.com/${head.slice("github:".length)}.git`, ref: ref ?? null };
  if (/^[\w.-]+\/[\w.-]+$/.test(head)) return { url: `https://github.com/${head}.git`, ref: ref ?? null };
  return { url: head, ref: ref ?? null };
}
async function fetchModuleSpec(spec) {
  if (!GIT_SPEC.test(spec)) return { dir: path18.resolve(spec), cleanup: async () => {
  } };
  const { url, ref } = gitSpecToClone(spec);
  const tmp = await fs18.mkdtemp(path18.join(os5.tmpdir(), "isocan-module-"));
  const args = ["clone", "--quiet", "--depth", "1", ...ref ? ["--branch", ref] : [], url, tmp];
  const cloned = spawnSync5("git", args, { encoding: "utf8" });
  if (cloned.status !== 0) {
    await fs18.rm(tmp, { recursive: true, force: true });
    throw new Error(`could not clone ${url}${ref ? `#${ref}` : ""}: ${(cloned.stderr || "").trim().split("\n").pop() ?? "git failed"}`);
  }
  const dir = existsSync6(path18.join(tmp, "manifest.json")) ? tmp : path18.join(tmp, "build");
  return { dir, cleanup: () => fs18.rm(tmp, { recursive: true, force: true }) };
}
