async function currentText(ctx, canvasId, item) {
  const version4 = item.versions.find((v) => v.id === item.currentVersionId) ?? item.versions.at(-1);
  return version4 ? (await ctx.client.downloadBlob(canvasId, version4.blobHash)).toString("utf8") : "";
}
